// GERADO POR scripts/assar-nuvem.mjs — não editar à mão.
//
// Nuvem de 46000 pontos amostrados na superfície de "tree wit vine 3.glb",
// ponderando por área. Coordenadas quantizadas em 16 bits, centradas na base
// e normalizadas para que o maior lado meça 1: multiplique pelo tamanho que
// quiser. Ver o cabeçalho do script para o porquê de assar em vez de carregar.
//
// Malhas lidas: 1 · triângulos: 2119607
export const PONTOS = 46000;
const Q = '';

export function nuvem() {
  const bytes = Uint8Array.from(atob(Q), (c) => c.charCodeAt(0));
  const q = new Int16Array(bytes.buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i] / 32767;
  return out;
}

const C = '';

/** A cor que a textura do modelo tinha em cada ponto, de 0 a 1. */
export function cores() {
  const bytes = Uint8Array.from(atob(C), (c) => c.charCodeAt(0));
  const out = new Float32Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) out[i] = bytes[i] / 255;
  return out;
}
